"use strict";(self.webpackChunkchzhshch_blog=self.webpackChunkchzhshch_blog||[]).push([["93935"],{93765(e,n,t){t.r(n),t.d(n,{metadata:()=>s,default:()=>c,frontMatter:()=>r,contentTitle:()=>i,toc:()=>l,assets:()=>h});var s=JSON.parse('{"id":"2002posts/2002poems2","title":"","description":"Without wine, meals have no flavor; without poetry, wine has no interest. Having drunk up the water of a thousand rivers, how can one utter a single word?","source":"@site/i18n/en/docusaurus-plugin-content-docs/current/2002posts/2002poems2.md","sourceDirName":"2002posts","slug":"/2002posts/2002poems2","permalink":"/en/2002posts/2002poems2","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"id":"2002poems2","title":"","hide_table_of_contents":true,"sidebar_label":"Collection of Xiaoren1\'s works from one month online (excluding content too inappropriate for children)"},"sidebar":"y2002postsSidebar","previous":{"title":"One five-character and one seven-character regulated verse celebrating Xiaoren1\'s banning from Guoxue and Guxiang forums","permalink":"/en/2002posts/2002poems1"},"next":{"title":"Great news from China\'s lewd forums","permalink":"/en/2002posts/2002poems3"}}'),a=t(74848),o=t(28453);let r={id:"2002poems2",title:"",hide_table_of_contents:!0,sidebar_label:"Collection of Xiaoren1's works from one month online (excluding content too inappropriate for children)"},i="Collection of Poems Written by Xiaoren1 in His First Month Online (The Too-Not-For-Children Ones Are Excluded)",h={},l=[];function d(e){let n={h1:"h1",header:"header",p:"p",...(0,o.R)(),...e.components};return(0,a.jsxs)(a.Fragment,{children:[(0,a.jsx)(n.header,{children:(0,a.jsx)(n.h1,{id:"collection-of-poems-written-by-xiaoren1-in-his-first-month-online-the-too-not-for-children-ones-are-excluded",children:"Collection of Poems Written by Xiaoren1 in His First Month Online (The Too-Not-For-Children Ones Are Excluded)"})}),"\n",(0,a.jsx)(n.p,{children:"Without wine, meals have no flavor; without poetry, wine has no interest. Having drunk up the water of a thousand rivers, how can one utter a single word?"}),"\n",(0,a.jsx)(n.p,{children:"Clouds confuse and mist obscures the old pavilion pool; her longing and his love remain unresolved. What day will the spring night see your rising again? Across the river, wind and rain are all lustful verse."}),"\n",(0,a.jsx)(n.p,{children:"Spring comes but flowers won't bloom; rain scatters but birds still cry. The moon surges through the waters of a thousand rivers \u2014 who can say what is high and what is low?"}),"\n",(0,a.jsx)(n.p,{children:"In the human world, life's grievances are empty \u2014 wine, lust, wealth, fame \u2014 desires all differ. Why does Eden have its forbidden fruit? Who seeks sin, dreaming in heaven?"}),"\n",(0,a.jsx)(n.p,{children:"When nature is frequent, thought grows frequent too; when thought is frequent, the tongue grows poor. Heaven and earth are but a single sheet of paper \u2014 each character, a star."}),"\n",(0,a.jsx)(n.p,{children:"The wallet is nearly dry \u2014 who will fill it up? The poetry forum has its Springs and Autumns \u2014 yet it's the Kangxi-Qianlong era again."}),"\n",(0,a.jsx)(n.p,{children:"Traces of the Great Wall still visible; what a pity the Epang Palace is already gone. The First Emperor had many benevolent policies \u2014 he just buried some rotten scholars."}),"\n",(0,a.jsx)(n.p,{children:"Where in heaven and earth is there not purity? Confucius the Second deleted poems and falsely claimed sagehood. From then on, heaven and earth had but one color \u2014 a thousand years and yet ten thousand years of flourishing."}),"\n",(0,a.jsx)(n.p,{children:"Climbing the west tower alone, the moonlight cool; Jinling spring rain drips on red blossoms. A thousand years of refined scholars across the divine continent \u2014 winning a landscape ten thousand miles long."}),"\n",(0,a.jsx)(n.p,{children:"A thousand years of great scholars, so many \u2014 yet none compares to a single commoner. Even hearing the dharma is still at one remove \u2014 who is attached to applause?"}),"\n",(0,a.jsx)(n.p,{children:"Xiaoren is no sir \u2014 just a floating duckweed on the vast sea. The four great elements have yet to settle \u2014 drifting with waves and riding the swells."}),"\n",(0,a.jsx)(n.p,{children:"No need to look at the appearance \u2014 naturally an ugly freak. Sallow-faced and bony-thin \u2014 but the heart is still quite wicked."}),"\n",(0,a.jsx)(n.p,{children:"Why play these games? The lofty gentlemen never get things right. Tang wind linked with Song rain \u2014 a thousand years and still no clearing."}),"\n",(0,a.jsx)(n.p,{children:"Qi is deviant, heart is deviant, nature too is deviant \u2014 deviant and straight coiled like a snake. Green mountains don't necessarily carry flowing water \u2014 above, floating clouds half-conceal them."}),"\n",(0,a.jsx)(n.p,{children:"A guest within the net of red dust \u2014 what traps me is this knowing. Without knowing, heaven and earth are vast \u2014 everywhere, wonders of their own."}),"\n",(0,a.jsx)(n.p,{children:"Without mind, mind has already settled \u2014 yet mind settled is neither being nor nonbeing. Being and nonbeing both unsettled \u2014 still only halfway there."}),"\n",(0,a.jsx)(n.p,{children:"Burdened in the red dust by this body \u2014 who is not a corpse-bearer? Body comes, body goes, with nowhere to rest \u2014 heaven and earth always retain one point of truth."}),"\n",(0,a.jsxs)(n.p,{children:["Lofty scholars are all old men \u2014 Xiaoren's head is not yet old \u2014 Lofty scholars often lie about lazily \u2014 Xiaoren must rise early",(0,a.jsx)("br",{}),"\nLofty scholars gnaw on book covers \u2014 Xiaoren's belly is full of grass \u2014 Too much grass to chew the cud \u2014 can't even think straight",(0,a.jsx)("br",{}),'\nThough just a rice weevil \u2014 can\'t tell millet from paddy \u2014 Sees a beard and calls him "sir" \u2014 sees a bosom and calls her "ma\'am"',(0,a.jsx)("br",{}),"\nAlways making jokes \u2014 everywhere a living treasure \u2014 Body like a three-inch nail \u2014 bone-thin, skin pallid",(0,a.jsx)("br",{}),"\nShoes covered in bird droppings \u2014 clothes covered in fleas \u2014 Never scrapes off the dried mud \u2014 never sweeps the filthy dust",(0,a.jsx)("br",{}),"\nHas one more bad habit \u2014 wants to hug everyone on sight \u2014 Regardless of beauty or ugliness \u2014 young lady or village crone",(0,a.jsx)("br",{}),"\nDay and night, clouds tumble and rain falls \u2014 features already withered \u2014 Looks like it won't be long \u2014 before being wrapped in white shroud",(0,a.jsx)("br",{}),"\nNot a single redeeming quality \u2014 but one good thing \u2014 Doesn't eat the emperor's grain \u2014 doesn't wear the master's coat",(0,a.jsx)("br",{}),"\nNo incense burned at temples \u2014 no prayers at churches \u2014 No yearning for heavenly halls \u2014 no longing for overseas islands",(0,a.jsx)("br",{}),"\nNot-dharma in the dharma of dharma \u2014 not-Dao in the Dao of Dao \u2014 No heart and no lungs \u2014 not a worry in the world",(0,a.jsx)("br",{}),"\nHair black or hair white \u2014 teeth black or teeth bright \u2014 Xiaoren or lofty scholar \u2014 all are made of clay",(0,a.jsx)("br",{}),"\nThe lofty scholar does nothing special \u2014 eats, pisses, and bathes \u2014 Once the great name is established \u2014 everything goes upside down",(0,a.jsx)("br",{}),"\nShark fin secretly scooped with rice \u2014 eating jujubes in front of others \u2014 Watching the sun set at South Mountain \u2014 under moonlight, visiting the madam",(0,a.jsx)("br",{}),"\nInner sage blows hot air \u2014 outer king stirs the paste \u2014 Talks literature and talks war \u2014 opens his mouth and rhetoric pours out",(0,a.jsx)("br",{}),"\nLooks down on everyone \u2014 tests anyone he meets \u2014 His tone bigger than the sky \u2014 wants to protect the people",(0,a.jsx)("br",{}),"\nIn the end, just a rotten skin-bag \u2014 better to blow up a bunker \u2014 Or maybe stuff in some medicine \u2014 tie it up and let it dry",(0,a.jsx)("br",{}),"\nFive thousand years from now \u2014 might be studied and debated \u2014 Why emulate the First Emperor \u2014 vainly preserving one's youth",(0,a.jsx)("br",{}),"\nDig a hole on the hilltop \u2014 wield an iron pick at the grave mound \u2014 Bury heaven and bury earth \u2014 who says heaven and earth are vast",(0,a.jsx)("br",{}),"\nDon't plant catalpa on the north hill \u2014 don't plant oak on the south \u2014 The wild goose's claw leaves no trace \u2014 who cares how vast heaven and earth are"]}),"\n",(0,a.jsx)(n.p,{children:"Please again and again \u2014 the great men always get their way. The Yellow River's water won't clear \u2014 a thousand years and still no peace."}),"\n",(0,a.jsx)(n.p,{children:"Wind is high, rain still fierce \u2014 every household shuts its doors. The Yellow River, thousands of miles \u2014 how much soil sinks in its current."}),"\n",(0,a.jsx)(n.p,{children:"Don't take chapters out of context \u2014 it's neither form nor vessel. If you don't look at a thousand years of bamboo \u2014 every one of them is a cruel magistrate."}),"\n",(0,a.jsx)(n.p,{children:"After three rounds, none have scored \u2014 could work as a Viagra sales manager. Chickens, ducks, cows, sheep, pigs, mules, horses \u2014 from today, all under heaven are one family."}),"\n",(0,a.jsx)(n.p,{children:"Can poetry reach the heights of Yellow Crane Tower? That's beyond my ability \u2014 equality and freedom are all detestable. Ghosts and monsters, humans and demons each have their preferences \u2014 which Enlightenment figure can serve as a beacon?"}),"\n",(0,a.jsx)(n.p,{children:"As if playing, as if gaming \u2014 how can form and qi bind you? The wild goose flies a thousand miles away \u2014 who still insists on boring through?"}),"\n",(0,a.jsx)(n.p,{children:"A wanderer of the three realms \u2014 neither gods nor ghosts are deluded. On the day before King Yama's court \u2014 even without wine, we'll sit face to face."}),"\n",(0,a.jsx)(n.p,{children:"On stage and below the stage, it's all a show \u2014 who among them is drunk? Illusory people create illusory scenes \u2014 don't try to interpret their meaning."}),"\n",(0,a.jsxs)(n.p,{children:["Has the summer heat ever truly oppressed? It's just people going topsy-turvy.",(0,a.jsx)("br",{}),"\nWater and fire, their natures like illusion \u2014 fish and shrimp throw themselves into the cauldron.",(0,a.jsx)("br",{}),"\nAll things, their forms both empty and existent \u2014 circles and squares, what binds what?",(0,a.jsx)("br",{}),"\nGlass and clay are one body \u2014 perpetually reflecting and shimmering.",(0,a.jsx)("br",{}),"\nPeople are blind not because of their eyes \u2014 it has nothing to do with light being strong or weak.",(0,a.jsx)("br",{}),"\nTrees dense or sparse \u2014 the cicada's tune is hard to rely on.",(0,a.jsx)("br",{}),"\nDusty thoughts chase after carriages \u2014 how can outlines be preserved?",(0,a.jsx)("br",{}),"\nProsperity flourishes then declines \u2014 love has always been thin.",(0,a.jsx)("br",{}),"\nIn the great furnace between heaven and earth \u2014 birth and death, who can grasp them?",(0,a.jsx)("br",{}),"\nParting thoughts ride the wind away \u2014 passing over mountains and ravines.",(0,a.jsx)("br",{}),"\nNo self, no non-self \u2014 if you don't understand, don't force interpretations."]}),"\n",(0,a.jsx)(n.p,{children:"Ascending the hall: Airs, Elegantiae, Hymns; under the covers: Jin Ping Mei. Confucius the Second's descendants are thriving \u2014 always occupying the high platform."}),"\n",(0,a.jsx)(n.p,{children:"The four great elements combine by chance \u2014 following karma, each goes east or west. The tide comes, spring waters rush \u2014 unaware they've already crossed the dyke."}),"\n",(0,a.jsxs)(n.p,{children:["Xiaoren asks the moderator: which words cannot be uttered? In the grand mansion with deep gates, what kind of tree should be planted? If one plants wrong, will one be reported to the authorities?",(0,a.jsx)("br",{}),"\nMy ears have been hard of hearing all my life \u2014 I can't hear the drum before the hall. Blind and cannot see \u2014 the rules and squares on the pillars. I only feel the road ahead is dark \u2014 as if there are knives and axes.",(0,a.jsx)("br",{}),"\nIn short, for us common folk \u2014 left or right, it's all suffering."]}),"\n",(0,a.jsx)(n.p,{children:"Colors and claws \u2014 all spoken for the blind. One should speak in one's native tongue \u2014 slavishly copying the ancients is mere parrotry."}),"\n",(0,a.jsx)(n.p,{children:"When the mind gives rise to demons, demons arise of themselves \u2014 when will it ever end? Looking ahead at the road to the Yellow Springs \u2014 how many seconds remain?"}),"\n",(0,a.jsxs)(n.p,{children:["Heaven and earth are clean everywhere \u2014 where does filth come from? All things are equal without difference \u2014 only the mediocre cling to love. The lotus boat is empty and void \u2014 it can carry anything.",(0,a.jsx)("br",{}),"\nRecognize the treasure within your robe \u2014 don't be obstructed by words."]}),"\n",(0,a.jsxs)(n.p,{children:["Discussing matters without being stuck on the matter \u2014 yes is still yes. Stuck on the matter without discussing it \u2014 just treat it as a game. The lofty pavilion doesn't find itself filthy \u2014 the latrine doesn't pinch its nose.",(0,a.jsx)("br",{}),"\nHeaven and earth are spacious everywhere \u2014 where can one not sleep?"]}),"\n",(0,a.jsx)(n.p,{children:"Without spear and without head \u2014 the mediocre oppose themselves. Heaven and earth are but floating bubbles \u2014 nobody is worthy."}),"\n",(0,a.jsx)(n.p,{children:"Under the First Emperor's blade, tens of thousands of corpses \u2014 Li Si carved inscriptions on stone. It's just that the book-burning was too soft-hearted \u2014 later generations of the poetry forum surpassed their predecessors."}),"\n",(0,a.jsxs)(n.p,{children:["Pitiful guest within the net \u2014 spinning in confusion.",(0,a.jsx)("br",{}),"\nWho dwells among the four great elements? Who enters heaven and earth's cauldron?",(0,a.jsx)("br",{}),"\nForm and spirit, empty and existent \u2014 what binds, what is bound?",(0,a.jsx)("br",{}),"\nArising from conditions, not a unity \u2014 like illusions, reflecting and shimmering.",(0,a.jsx)("br",{}),"\nIn confusion, knowing begins with objects \u2014 worries arise from youth.",(0,a.jsx)("br",{}),"\nThe five aggregates are falsely woven \u2014 form and vessel cannot be relied on.",(0,a.jsx)("br",{}),"\nDusty thoughts chase after conditions \u2014 the three realms, desolate and vast.",(0,a.jsx)("br",{}),"\nHabitual tendencies dissolve as one walks \u2014 don't let the field of merit grow thin.",(0,a.jsx)("br",{}),"\nThe blind turtle crosses the bitter sea \u2014 how can the floating log be found?",(0,a.jsx)("br",{}),"\nVainglory is a dream in a mirror \u2014 in an instant, boat and ravine are gone.",(0,a.jsx)("br",{}),"\nWhere is the poor man's robe? \u2014 The bright pearl is there, truly there."]}),"\n",(0,a.jsx)(n.p,{children:"Under the First Emperor's blade, a ghost \u2014 on the internet, a person beside the axe. Don't blame it on the red dust within \u2014 there are so many ass-kissing ministers nowadays."}),"\n",(0,a.jsx)(n.p,{children:"The Human King and the Demon King \u2014 who among them lacks logic? Why must one always be right? Nobody is going to get worked up over you."}),"\n",(0,a.jsx)(n.p,{children:"The Human King and the Demon King \u2014 who among them doesn't serve the people? It's just that when it's time to pay the bill \u2014 they want copper and they want silver."}),"\n",(0,a.jsx)(n.p,{children:'The character for "official" has two mouths \u2014 always making up stories. No wonder the reports are full of \u2014 nothing but fake numbers.'}),"\n",(0,a.jsx)(n.p,{children:"Warning after warning \u2014 handing out big hats at the sight of a head. No one is worth cursing \u2014 not even a bandit."}),"\n",(0,a.jsx)(n.p,{children:"Open schemes and hidden schemes \u2014 no reasons needed. As long as the officials have mouths \u2014 the Yellow River can flow westward."}),"\n",(0,a.jsx)(n.p,{children:"Moderator and Xiaoren \u2014 naturally quite different. The moderator wears a feathered cap \u2014 Xiaoren doesn't have a copper coin."}),"\n",(0,a.jsx)(n.p,{children:"Hands err but the heart does not \u2014 foolish the person, more foolish the love. Next year when flowers send their word \u2014 together we'll plant bamboo branches."}),"\n",(0,a.jsx)(n.p,{children:"Games in the mirror raise dust indeed \u2014 why take everything so seriously? The snow-print remains briefly, the wild goose long gone \u2014 don't look at phantom shadows and add needless anger."}),"\n",(0,a.jsxs)(n.p,{children:["Rain ends, the long sky clear and pure \u2014 set sail departing from the distant bay.",(0,a.jsx)("br",{}),"\nVast waves ten thousand miles away \u2014 shattered sun stirs golden shimmer.",(0,a.jsx)("br",{}),"\nClouds dry on trees at heaven's edge \u2014 wind shifts the mountains on the sea.",(0,a.jsx)("br",{}),"\nCome drink the ocean's boundless wine \u2014 and sprinkle once to intoxicate the mortal world."]}),"\n",(0,a.jsxs)(n.p,{children:["In August, treading the waves across the grey-green sea \u2014 whale-surges, cruel waves swallowing the distant sky.",(0,a.jsx)("br",{}),"\nRaging dragons crack stone, clouds spew ink \u2014 startled steeds overturn carts, the sun loses its red.",(0,a.jsx)("br",{}),"\nSince ancient times, heroes have had fire-blood \u2014 today's personages are all gold and bronze.",(0,a.jsx)("br",{}),"\nThe great Peng spreads its wings, embracing the cosmos \u2014 through ten thousand kalpas, heaven and earth are shaken in one tremor."]}),"\n",(0,a.jsx)(n.p,{children:"Pick up the brush and stand a thousand words \u2014 why need a draft in the belly? Poetry is also prose \u2014 don't draw a circle and imprison yourself."}),"\n",(0,a.jsx)(n.p,{children:"The prophet dies before his time \u2014 a hundred generations leave their branches. Fooling gods and fooling ghosts \u2014 everywhere playing at miracles."}),"\n",(0,a.jsx)(n.p,{children:"Forced to change one's name \u2014 why are heaven and earth so blind? Smash the sun and moon to pieces \u2014 and heaven and earth will find their own peace."}),"\n",(0,a.jsxs)(n.p,{children:["The Way of Heaven is originally nothing \u2014 suffering gathers in emptiness and existence.",(0,a.jsx)("br",{}),"\nThe void shatters of itself \u2014 clinging to it like straw dogs.",(0,a.jsx)("br",{}),"\nMountains are and are not mountains \u2014 shedding the collar, no elbows left.",(0,a.jsx)("br",{}),"\nWithout true contemplation \u2014 don't pretend to roar like a lion."]}),"\n",(0,a.jsxs)(n.p,{children:["Death is illusion as life is illusion \u2014 who would torment themselves over every affair.",(0,a.jsx)("br",{}),"\nEven dharma-marks should be abandoned, let alone non-dharma \u2014 the oars must be left behind, how much more the ferry-boat.",(0,a.jsx)("br",{}),"\nA thousand carts of yellow scrolls still blind the eyes \u2014 that single point on the spiritual terrace has nothing to do with conditions.",(0,a.jsx)("br",{}),"\nWithin the bounds of Great Tang there is no knowledge \u2014 when has the bright mirror ever hung outside its own reflection."]}),"\n",(0,a.jsx)(n.p,{children:"To be great, one must be large \u2014 above and below are always reliable. The autumn wind is not for the leaves \u2014 it just carries away the red clouds."}),"\n",(0,a.jsx)(n.p,{children:"Not yet divided but already split \u2014 wasting mouth and tongue for nothing. On the Eastern Sea, raging fire \u2014 another track left in the void."}),"\n",(0,a.jsx)(n.p,{children:"Here comes one-thirty again \u2014 Xiaoren must duck out first. Haven't yet eaten lunch \u2014 already breathing my last."}),"\n",(0,a.jsx)(n.p,{children:"Red peach dances with light sleeves \u2014 zither and lute sing in harmony. From before the hall, a dark fragrance drifts \u2014 stirring waves across the entire sky."}),"\n",(0,a.jsx)(n.p,{children:"Vast, vast is the universe \u2014 yet it can't hold a few characters. Sun and moon are originally colorless \u2014 once they enter the eyes, they breed incidents."}),"\n",(0,a.jsx)(n.p,{children:"Better to banter a bit less \u2014 there should be some substance in the belly. A puff of pure smoke through the nostril \u2014 beats eating jujubes."}),"\n",(0,a.jsx)(n.p,{children:"Wearing straw and dark shades \u2014 iron palm skimming over water. Without eyes, heaven and earth are vast \u2014 planting bean sprouts in fire."}),"\n",(0,a.jsx)(n.p,{children:"What cannot be said is best left unsaid \u2014 saying it only wastes the tongue. How dare the wronged wife speak \u2014 there isn't even June snow."}),"\n",(0,a.jsx)(n.p,{children:"The mountain flies but clouds don't move \u2014 the wind stops but shadows still drift. Brushing the sea, whales overturn the waves \u2014 heaven and earth fit in one gourd."}),"\n",(0,a.jsx)(n.p,{children:"Light flows, the sky's reflection clean \u2014 mountain sounds remote as emptiness. A single path unknown to man \u2014 flickering in and out of the evening clouds."}),"\n",(0,a.jsxs)(n.p,{children:["Unborn, rejoicing all day long \u2014 where does the doubt of birth and death come from? \u2014 Doubt arises because one clings to having \u2014 having clings, and thus entanglement begins",(0,a.jsx)("br",{}),"\nFloating clouds: fame for ten thousand ages \u2014 dung and earth: tombstones for a thousand years \u2014 This body has nowhere else to lodge \u2014 not yet settled, already departed",(0,a.jsx)("br",{}),"\nWillows lingering by the riverside \u2014 deer calling in the forest \u2014 Every day is a good day \u2014 every hour is the hour of blossoming",(0,a.jsx)("br",{}),"\nThe tide rises and falls again \u2014 the moon waxes and wanes \u2014 The world has not so many troubles \u2014 why fuss about action or inaction",(0,a.jsx)("br",{}),'\nDon\'t steal the pearl upon the dust \u2014 don\'t cling to wonders in the dharma \u2014 Can the bright pearl belong to "having"? \u2014 To say "nothing" is also foolish',(0,a.jsx)("br",{}),"\nWhen having and nothing are both abandoned \u2014 one is still in the ghost-realm of thought \u2014 Sit and watch heaven and earth turn \u2014 stand and watch heaven and earth hang",(0,a.jsx)("br",{}),"\nWild geese fly, wind over water \u2014 flowers fall, moonlight on the branch \u2014 Every dharma is unstained \u2014 not a mote of dust is left behind",(0,a.jsx)("br",{}),"\nVast and boundless, the mundane and sacred dissolve \u2014 serene, entering joy and sorrow \u2014 Birth and death met with a single laugh \u2014 purity and filth, both left to be",(0,a.jsx)("br",{}),"\nBirth-and-death: the grace of sentient beings \u2014 purity-and-filth: the compassion of sentient beings \u2014 Empty flowers perform the Buddha's work \u2014 the illusory mirror plays with the Demon Master",(0,a.jsx)("br",{}),"\nTo face calamity, a thousand bodies go \u2014 through hardship, one vow follows \u2014 Is Avici Hell empty or not yet empty? \u2014 Is Bodhi attained or not yet attained?",(0,a.jsx)("br",{}),"\nThe song of the qin, naturally serene and drifting \u2014 don't peer into the moon for answers"]})]})}function c(e={}){let{wrapper:n}={...(0,o.R)(),...e.components};return n?(0,a.jsx)(n,{...e,children:(0,a.jsx)(d,{...e})}):d(e)}},28453(e,n,t){t.d(n,{R:()=>r,x:()=>i});var s=t(96540);let a={},o=s.createContext(a);function r(e){let n=s.useContext(o);return s.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function i(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(a):e.components||a:r(e.components),s.createElement(o.Provider,{value:n},e.children)}}}]);